INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4871211', 'Hephthalite–Sasanian War of 484', 'The Hephthalite–Sasanian War of 484 was a military confrontation that took place in 484 between an invading force of the Sasanian Empire under the command of Peroz I and a smaller army of the Hephthalite Empire under the command of Khushnavaz. The battle was a catastrophic defeat for the Sasanian forces, who were completely swept out.', 484, NULL, NULL, NULL, NULL, NULL, 'year', '484', 43, 'https://en.wikipedia.org/wiki/Hephthalite%E2%80%93Sasanian_War_of_484'),
  ('Q4548218', 'Siege of Bamyan', 'The siege of Bamyan (Dari: محاصره بامیان) took place in the spring of 1221 A.D. during the Mongol invasion of Khorasan by an army under the leadership of Genghis Khan, ruler of the Mongol Empire, who was in pursuit of Sultan Jalal al-Din Mangburni, the last ruler of the Khwarazmian Empire. Genghis Khan crossed the Hindu Kush and after that besieged the citadel of Shahr-e-Gholghola near Bamyan, northwest of Kabul, in present-day Afghanistan.', 1221, 7, NULL, 1221, NULL, NULL, 'month', '1221', 43, 'https://en.wikipedia.org/wiki/Siege_of_Bamyan'),
  ('Q7509853', 'Siege of Balkh', 'The Timurid conquests and invasions started in the late 14th century with Timur''s control over the Chagatai Khanate and ended at the start of the 15th century with the death of Timur. Due to the sheer scale of Timur''s wars, and due to the fact that he was generally undefeated in battle, he has been regarded as one of the most successful military commanders of all time.', 1370, NULL, NULL, NULL, NULL, NULL, 'year', '1370', 45, 'https://en.wikipedia.org/wiki/Siege_of_Balkh_(1370)'),
  ('Q16931483', 'Mughal–Safavid War', 'The Mughal–Safavid war of 1649–1653 was fought between the Mughal and Safavid empires in the territory of modern Afghanistan. While the Mughals were at war with the Janid Uzbeks, the Safavid army captured the fortress city of Kandahar and other strategic cities that controlled the region.', 1649, NULL, NULL, 1653, NULL, NULL, 'year', '1649–1653', 48, 'https://en.wikipedia.org/wiki/Mughal%E2%80%93Safavid_war_(1649%E2%80%931653)'),
  ('Q7510145', 'Siege of Kandahar', 'The Siege of Kandahar (Persian: محاصرهٔ قندهار) began when Nader Shah''s Afsharid army invaded southern Afghanistan to topple the last Hotaki stronghold of Loy Kandahar, which was held by Hussain Hotaki. It took place in the Old Kandahar area of the modern city of Kandahar in Afghanistan and lasted until March 24, 1738, when the Hotaki Afghans were defeated by the Persian army, namely the Afsharid empire.', 1737, 4, NULL, 1738, 3, 24, 'month', 'April 1737 – 24 March 1738', 45, 'https://en.wikipedia.org/wiki/Siege_of_Kandahar'),
  ('Q1010245', 'Battle of Ghazni', 'The Battle of Ghazni took place in the city of Ghazni in central Afghanistan on Tuesday, 23 July 1839, during the First Anglo-Afghan War.', 1839, 7, 23, NULL, NULL, NULL, 'day', '23 July 1839', 41, 'https://en.wikipedia.org/wiki/Battle_of_Ghazni'),
  ('Q908888', '1842 retreat from Kabul', 'The Battle of Gandamak was the defeat of the last remnant of a British-Indian force in the 1842 retreat from Kabul during the First Anglo-Afghan War. On 13 January 1842, the few remaining survivors of General William George Keith Elphinstone''s 4500 soldiers who had begun the retreat were overwhelmed by a horde of Afghan tribesmen.', 1842, NULL, NULL, 1842, 1, 13, 'year', '1842', 45, 'https://en.wikipedia.org/wiki/Battle_of_Gandamak'),
  ('Q370307', 'Battle of Kandahar', 'The Battle of Kandahar, 1 September 1880, was the last major conflict of the Second Anglo-Afghan War. The battle in southern Afghanistan was fought between the British forces under command of General Roberts and the Afghan forces led by Ayub Khan.', 1880, 9, 1, NULL, NULL, NULL, 'day', '1 September 1880', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kandahar_(1880)'),
  ('Q548625', 'Battle of Maiwand', 'The Battle of Maiwand was fought on 27 July 1880 during the Second Anglo-Afghan War. Fought near the village of Maiwand in Kandahar Province, the battle resulted in an Afghan army of 12,000 composed of 9,000 infantry and 3,000 cavalry under Mohammad Ayub Khan defeating a force of 2,500 British and Indian troops under Brigadier-general George Burrows.', 1880, 7, 27, NULL, NULL, NULL, 'day', '27 July 1880', 58, 'https://en.wikipedia.org/wiki/Battle_of_Maiwand'),
  ('Q1456454', 'Anglo-Afghan Treaty of 1919', 'The Anglo-Afghan Treaty of 1919, also known as the Treaty of Rawalpindi, was a bilateral treaty which brought the Third Anglo-Afghan War to an end.', 1919, 8, 8, NULL, NULL, NULL, 'day', '8 August 1919', 64, 'https://en.wikipedia.org/wiki/Anglo-Afghan_Treaty_of_1919'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q10952572', 'Afghan Civil War (1928–1929)', 'The Afghan Civil War of 1928–1929 was fought from 14 November 1928 to 13 October 1929. Rebelling, and subsequently governing Saqqawist (Saqāwīhā) forces under Habibullāh Kalakāni fought against various opposing tribes and rival monarchs in the Kingdom of Afghanistan, among whom Mohammed Nādir Khān eventually achieved a preponderant role.', 1929, NULL, NULL, 1929, 10, 13, 'decade', '1920s', 52, 'https://en.wikipedia.org/wiki/Afghan_Civil_War_(1928%E2%80%931929)'),
  ('Q30070166', '1973 Afghan coup d''état', 'The 1973 Afghan coup d''état, locally known as the Coup of 26 Saratan, The National Revolution and self-proclaimed as the Revolution of 26 Saratan 1352, was led by Army General and prince Mohammad Daoud Khan against his cousin, King Mohammad Zahir Shah, on 17 July 1973, which resulted in the establishment of the Republic of Afghanistan under a one-party system led by Daoud Khan. For the coup, Daoud Khan led forces in Kabul along with then-chief of staff General Abdul Karim Mustaghni, to overthrow the monarchy while the King was convalescing abroad in Ischia, Italy.', 1973, 7, 17, NULL, NULL, NULL, 'day', '17 July 1973', 55, 'https://en.wikipedia.org/wiki/1973_Afghan_coup_d''%C3%A9tat'),
  ('Q3080960', 'Siege of Khost', 'The eleven-year siege of Khost took place throughout the nine-year Soviet–Afghan War in the 1980s and the subsequent Afghan civil war in the 1990s. Its airstrip''s 3 km runway served as a base for helicopter operations by Soviet forces.', 1980, 1, NULL, 1991, 4, 11, 'month', 'January 1980 – 11 April 1991', 45, 'https://en.wikipedia.org/wiki/Siege_of_Khost'),
  ('Q1392933', 'Battle for Hill 3234', 'The Battle for Hill 3234 (Russian: Бой у высоты 3234, romanized: Boy u vysoty 3234) was a successful attack battle fought by the 9th Company of the 345th Independent Guards Airborne Regiment, Soviet Airborne Troops, part of Operation Magistral, supported by the Afghan Army''s 15th Tank Brigade, 8th, 11th, 12th, 214th, 25th Infantry Division and the 37th Commando Battalion, in Afghanistan against a force of some 250 Mujahideen rebels who were supported by several Pakistani mercenaries in early January 1988. Two of the soldiers killed, Vyacheslav Aleksandrov and Andrey Melnikov, were…', 1988, 1, 7, 1988, 1, 8, 'day', '7 January 1988 – 8 January 1988', 57, 'https://en.wikipedia.org/wiki/Battle_for_Hill_3234'),
  ('Q1980081', 'Afghan Civil War', 'The 1992–1996 Afghan Civil War, also known as the Second Afghan Civil War, took place between 28 April 1992 — the date a new interim Afghan government was supposed to replace the Republic of Afghanistan of President Mohammad Najibullah—and the Taliban''s occupation of Kabul establishing the Islamic Emirate of Afghanistan on 27 September 1996. The war immediately followed the 1989–1992 civil war with the Mujahideen victory and dissolution of the Republic of Afghanistan in April 1992.', 1992, 4, 30, 1996, 9, 27, 'day', '30 April 1992 – 27 September 1996', 63, 'https://en.wikipedia.org/wiki/Afghan_Civil_War_(1992%E2%80%931996)'),
  ('Q4871359', 'Battle of Kabul', 'The Battle of Kabul was a series of intermittent battles and sieges over the city of Kabul during the period of 1992–1996. Throughout the Soviet–Afghan War from 1979 to 1989, and subsequent civil war (1989–1992) the city of Kabul saw little fighting.', 1992, 4, 30, 1996, 9, 27, 'day', '30 April 1992 – 27 September 1996', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kabul_(1992%E2%80%931996)'),
  ('Q12302518', 'Afghan Civil War', 'The 1996–2001 Afghan Civil War, also known as the Third Afghan Civil War, took place between the Taliban''s conquest of Kabul and their establishing of the Islamic Emirate of Afghanistan on 27 September 1996, and the U.S. invasion of Afghanistan on 7 October 2001: a period that was part of the Afghan Civil Wars that had started in 1989, and also part of the conflict (in wider sense) in Afghanistan that had started in 1978. The Islamic State of Afghanistan government remained the recognized government of Afghanistan by most of the international community.', 1996, 9, 27, 2001, 10, 7, 'day', '27 September 1996 – 7 October 2001', 64, 'https://en.wikipedia.org/wiki/Afghan_Civil_War_(1996%E2%80%932001)'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q1771651', 'Dasht-i-Leili massacre', 'In December 2001, between 250 and 2,000 Taliban insurgents who had surrendered to the National Islamic Movement of Afghanistan (part of the Northern Alliance) were massacred while being transported to Sheberghan Prison in the Jowzjan Province. Fighters loyal to General Abdul Rashid Dostum tightly packed the prisoners into shipping containers in Kunduz and sealed them inside, while denying them water and sustenance, and reportedly shot all those who had not died of suffocation by the time the convoy arrived at Sheberghan.', 2001, 12, NULL, NULL, NULL, NULL, 'month', 'December 2001', 47, 'https://en.wikipedia.org/wiki/Dasht-i-Leili_massacre'),
  ('Q2237280', 'Battle of Tora Bora', 'The Battle of Tora Bora occurred from 30 November to 17 December 2001, as part of the United States invasion of Afghanistan during the war in Afghanistan. It took place around the cave complex of Tora Bora in the Safed Koh mountain range, near Afghanistan''s eastern border with Pakistan.', 2001, 12, 6, 2001, 12, 17, 'day', '6 December 2001 – 17 December 2001', 60, 'https://en.wikipedia.org/wiki/Battle_of_Tora_Bora'),
  ('Q2889318', 'Fall of Mazari Sharif', 'The fall of Mazar-i-Sharif (or Mazar-e-Sharif) in November 2001 resulted from the first major offensive of the Afghanistan War after American intervention. A push into the city of Mazar-i-Sharif in Balkh Province by the United Islamic Front for the Salvation of Afghanistan (Northern Alliance), combined with U.S. Army Special Forces aerial bombardment, resulted in the withdrawal of Taliban forces who had held the city since 1998.', 2001, 11, 9, 2001, 11, 10, 'day', '9 November 2001 – 10 November 2001', 52, 'https://en.wikipedia.org/wiki/Fall_of_Mazar-i-Sharif'),
  ('Q3152953', '2001 uprising in Herat', 'The 2001 uprising in Herat was a coordinated insurrection and uprising in the Afghan city of Herat as part of the United States war in Afghanistan. The city was captured on November 12 by Northern Alliance forces as well as Special Forces of the United States, the United Kingdom and Iran.', 2001, 11, 12, 2001, 11, 12, 'day', '12 November 2001', 47, 'https://en.wikipedia.org/wiki/2001_uprising_in_Herat'),
  ('Q3180637', 'Battle of Qala-i-Jangi', 'The Battle of Qala-i-Jangi in Afghanistan (sometimes also referred to as the "Battle of Mazar-i-Sharif") was a six-day military engagement following an uprising of prisoners of war who had been taken into custody by U.S.-led coalition forces on 25 November 2001. The battle took place from 25 November to 1 December, in northern Afghanistan.', 2001, 11, 25, 2001, 12, 1, 'day', '25 November 2001 – 1 December 2001', 50, 'https://en.wikipedia.org/wiki/Battle_of_Qala-i-Jangi'),
  ('Q3485911', 'Siege of Kunduz', 'The siege of Kunduz occurred during the 2001 United States invasion of Afghanistan. After the fall of Mazar-i-Sharif on 9 November, the focus of the Northern Alliance advance shifted towards the city of Kunduz, which was the last remaining Taliban stronghold in northern Afghanistan.', 2001, 11, 20, 2001, 11, 23, 'day', '20 November 2001 – 23 November 2001', 43, 'https://en.wikipedia.org/wiki/Siege_of_Kunduz'),
  ('Q5432157', 'Fall of Kabul', 'Kabul, capital of Afghanistan, fell in November 2001 to the Northern Alliance forces during the war in Afghanistan. Northern Alliance forces began their attack on the city on 13 November and made swift progress against Taliban and al-Qaeda forces that were heavily weakened by American and British air strikes.', 2001, 11, 13, 2001, 11, 13, 'day', '13 November 2001', 52, 'https://en.wikipedia.org/wiki/Fall_of_Kabul_(2001)'),
  ('Q19646470', 'United States invasion of Afghanistan', 'Shortly after the September 11 attacks in 2001, the United States declared the war on terror and subsequently led a multinational military operation against Taliban-ruled Afghanistan. The stated goal was to dismantle al-Qaeda, which had executed the attacks under the leadership of Osama bin Laden, and to deny al-Qaeda militants a safe base of operations in Afghanistan by toppling the ruling Taliban government.', 2001, NULL, NULL, 2001, 12, 17, 'year', '2001', 56, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan'),
  ('Q1476042', 'Operation Anaconda', 'Operation Anaconda or the Battle of Shah-i-Kot was a military operation that took place in early March 2002 as part of the war in Afghanistan. CIA paramilitary officers, working with their allies, attempted to destroy al-Qaeda and Taliban forces.', 2002, NULL, NULL, 2002, 3, 18, 'year', '2002', 59, 'https://en.wikipedia.org/wiki/Operation_Anaconda'),
  ('Q210137', '2005 Kashmir earthquake', 'On 8 October 2005, at 08:50:39 PKT, a Mw 7.6 earthquake struck the Azad Kashmir region in northern Pakistan. Its epicenter was located in the tehsil of Patikka, near the city of Muzaffarabad.', 2005, 10, 8, NULL, NULL, NULL, 'day', '8 October 2005', 75, 'https://en.wikipedia.org/wiki/2005_Kashmir_earthquake'),
  ('Q3354826', 'Operation Red Wings', 'Operation Red Wings (often incorrectly referred to as Operation Redwing or Operation Red Wing), informally referred to as the Battle of Abbas Ghar, was a joint military operation conducted by the United States in the Pech District of Kunar Province, Afghanistan. It was carried out from late-June to mid-July 2005 on the slopes of Sawtalo Sar, a mountain approximately 20 miles (32 km) west of the provincial capital of Asadabad.', 2005, 6, 27, 2005, 7, NULL, 'day', '27 June 2005 – July 2005', 56, 'https://en.wikipedia.org/wiki/Operation_Red_Wings'),
  ('Q1485258', 'Battle of Chora', 'The Battle of Chora was a military engagement in Chora District, Uruzgan Province, Afghanistan, occurring from 15 to 19 June 2007. The battle was between ISAF – primarily composed of Dutch troops – and allied Afghan forces against anti-coalition militias (ACM), believed to be affiliated with the Taliban.', 2007, NULL, NULL, 2007, 6, 19, 'year', '2007', 45, 'https://en.wikipedia.org/wiki/Battle_of_Chora'),
  ('Q1616794', 'Operation Achilles', 'Operation Achilles was a NATO operation, part of the War in Afghanistan. Its objective was to clear Helmand province of the Taliban.', 2007, 5, 30, NULL, NULL, NULL, 'day', '30 May 2007', 53, 'https://en.wikipedia.org/wiki/Operation_Achilles'),
  ('Q2638382', 'Battle of Musa Qala', 'The Battle of Musa Qala (also Qaleh or Qal''eh) was a British-led military action in Helmand Province, southern Afghanistan, launched by the Afghan National Army and the International Security Assistance Force (ISAF) against the Taliban on 7 December 2007. After three days of intense fighting, the Taliban retreated into the mountains on 10 December.', 2007, 12, 7, 2007, 12, 12, 'day', '7 December 2007 – 12 December 2007', 48, 'https://en.wikipedia.org/wiki/Battle_of_Musa_Qala'),
  ('Q267418', 'Uzbin Valley ambush', 'French International Security Assistance Force (ISAF) troops were ambushed by Afghan Taliban insurgents, with heavy casualties, in the Uzbin Valley outside the village of Spēṟ Kunday in the Surobi District of Kabul province in eastern Afghanistan on 18 August 2008. In the ambush and subsequent counter-attack operations involving reinforcements, 10 French soldiers were killed, as well as the Afghan interpreter; 21 French soldiers and 2 to 4 Afghan soldiers were wounded, and 20 to 40 civilians also lost their lives.', 2008, 8, 18, 2008, 8, 19, 'day', '18 August 2008 – 19 August 2008', 43, 'https://en.wikipedia.org/wiki/Uzbin_Valley_ambush'),
  ('Q2890373', 'Battle of Wanat', 'The Battle of Wanat took place on July 13, 2008, when around 200 Taliban insurgents attacked American troops stationed in the Waygal district of Afghanistan''s far eastern Nuristan province. The distant position was primarily defended by United States Army soldiers with 2nd Platoon, Chosen Company, 2nd Battalion, 503rd Infantry Regiment (Airborne), 173rd Airborne Brigade Combat Team.', 2008, 7, 13, NULL, NULL, NULL, 'day', '13 July 2008', 43, 'https://en.wikipedia.org/wiki/Battle_of_Wanat'),
  ('Q2664174', 'Battle of Kamdesh', 'The Battle of Kamdesh took place during the War in Afghanistan. It occurred on October 3, 2009, when a force of 300 Taliban assaulted the American Combat Outpost ("COP") Keating near the town of Kamdesh in Nuristan Province in eastern Afghanistan.', 2009, 10, 3, NULL, NULL, NULL, 'day', '3 October 2009', 50, 'https://en.wikipedia.org/wiki/Battle_of_Kamdesh'),
  ('Q843588', 'Operation Moshtarak', 'Operation Moshtarak (Dari for Together or Joint), also known as the Battle of Marjah, was an International Security Assistance Force (ISAF) pacification offensive in the town of Marjah, Helmand Province, Afghanistan. It involved a combined total of 15,000 Afghan, American, British, Canadian, Danish, and Estonian troops, constituting the largest joint operation of the War in Afghanistan up to that point.', 2010, 2, 13, 2010, 12, 7, 'day', '13 February 2010 – 7 December 2010', 61, 'https://en.wikipedia.org/wiki/Operation_Moshtarak'),
  ('Q1263360', 'Kandahar massacre', 'The Kandahar massacre, also called the Panjwai massacre, was a mass murder that occurred in the early hours of 11 March 2012, when United States Army Staff Sergeant Robert Bales murdered 16 Afghan civilians and wounded six others in the Panjwayi District of Kandahar Province, Afghanistan. Nine of his victims were children, and 11 of the dead were from the same family.', 2012, 3, 11, NULL, NULL, NULL, 'day', '11 March 2012', 56, 'https://en.wikipedia.org/wiki/Kandahar_massacre'),
  ('Q12257020', 'National Airlines Flight 102', 'National Airlines Flight 102 (N8102/NCR102) was a cargo flight operated by National Airlines between Camp Bastion (now Camp Shorabak) near the city of Lashkargah in Afghanistan and Al Maktoum International Airport in Dubai, with a refueling stop at Bagram Airfield, Afghanistan. On April 29, 2013, the Boeing 747-400 operating the flight crashed within the perimeter of the Bagram Airfield moments after taking off, killing all seven people on board.', 2013, 4, 29, NULL, NULL, NULL, 'day', '29 April 2013', 57, 'https://en.wikipedia.org/wiki/National_Airlines_Flight_102'),
  ('Q14503653', '2013 Afghanistan–Pakistan floods', 'In August 2013, Pakistan and eastern Afghanistan experienced heavy rain that led to flash flooding. More than 180 died as a result of the floods.', 2013, 8, NULL, NULL, NULL, NULL, 'month', 'August 2013', 43, 'https://en.wikipedia.org/wiki/2013_Pakistan%E2%80%93Afghanistan_floods'),
  ('Q18920712', 'War in Afghanistan (2015–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2015, 1, 1, 2021, 8, 30, 'day', '1 January 2015 – 30 August 2021', 45, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2015%E2%80%932021)'),
  ('Q21030182', 'Battle of Kunduz', 'The Battle of Kunduz took place from April to October 2015 for control of the city of Kunduz, located in northern Afghanistan, with Taliban fighters attempting to seize the city and displace Afghan security forces. On 28 September 2015, the Taliban forces suddenly overran the city, with government forces retreating outside the city.', 2015, 4, 24, NULL, NULL, NULL, 'day', '24 April 2015', 51, 'https://en.wikipedia.org/wiki/Battle_of_Kunduz_(2015)'),
  ('Q23890868', 'April 2016 Kabul attack', 'On the morning of 19 April 2016, Taliban militants attacked a security team responsible for protecting government VIPs in Kabul, Afghanistan. The initial attack killed 64 people and wounded 347.', 2016, 4, 19, NULL, NULL, NULL, 'day', '19 April 2016', 45, 'https://en.wikipedia.org/wiki/April_2016_Kabul_attack'),
  ('Q25995756', 'July 2016 Kabul bombing', 'On 23 July 2016, a twin bombing occurred in the vicinity of Deh Mazang square in Kabul, capital of Afghanistan, when Enlightenment Movement protesters, mostly from the Hazara ethnic group, were marching against a decision to bypass their region in the development of the TUTAP mega power project. At least 97 people were killed and 260 injured.', 2016, 7, 23, NULL, NULL, NULL, 'day', '23 July 2016', 58, 'https://en.wikipedia.org/wiki/July_2016_Kabul_bombing'),
  ('Q29385187', 'April 2017 Achin airstrike', 'On 13 April 2017, the United States conducted an airstrike in Achin District, located in the Nangarhar Province of eastern Afghanistan, near the border with Pakistan. The airstrike was carried out using the largest non-nuclear weapon in the United States'' arsenal, the GBU-43/B Massive Ordnance Air Blast (MOAB), with the goal of destroying tunnel complexes used by the Islamic State – Khorasan Province (IS-KP).', 2017, 4, 13, NULL, NULL, NULL, 'day', '13 April 2017', 52, 'https://en.wikipedia.org/wiki/2017_Nangarhar_airstrike'),
  ('Q47501091', '2018 Kabul ambulance bombing', 'On 27 January 2018, an ambulance was used as a vehicle-borne improvised explosive device near Sidarat Square in Kabul, Afghanistan. At least 103 people were killed and 235 others wounded in the attack.', 2018, 1, 27, NULL, NULL, NULL, 'day', '27 January 2018', 56, 'https://en.wikipedia.org/wiki/Kabul_ambulance_bombing'),
  ('Q56085424', 'Ghazni offensive', 'The Ghazni offensive began on 10 August 2018, when Taliban fighters launched an assault on the city of Ghazni, Afghanistan''s sixth largest city and one which has been culturally and strategically important for much of the country''s history. The attack resulted in the deaths of hundreds of insurgents, soldiers, police, and civilians.', 2018, 8, 10, NULL, NULL, NULL, 'day', '10 August 2018', 43, 'https://en.wikipedia.org/wiki/Ghazni_offensive'),
  ('Q66554821', '17 August 2019 Kabul bombing', 'On 17 August 2019, a suicide bombing took place during a wedding in a wedding hall in Kabul, Afghanistan. At least 92 people were killed in the attack and over 140 injured.', 2019, 8, 17, NULL, NULL, NULL, 'day', '17 August 2019', 53, 'https://en.wikipedia.org/wiki/17_August_2019_Kabul_bombing'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q88650751', 'Kabul gurdwara attack', 'On 25 March 2020, ISIS gunmen and suicide bombers attacked the Gurdwara Har Rai Sahib (a Sikh shrine) in Kabul, Afghanistan. About 200 Sikh worshipers were reported to be in the building at the time, of which 25 worshippers were killed and at least 8 wounded after an hour-long siege which ended in all assailants being killed by the security forces.', 2020, 3, 25, NULL, NULL, NULL, 'day', '25 March 2020', 48, 'https://en.wikipedia.org/wiki/2020_Kabul_gurdwara_attack'),
  ('Q101095363', '2020 Kabul University attack', 'On 2 November 2020, three gunmen stormed the campus of Kabul University in Kabul, under the former Islamic Republic of Afghanistan, killing 32 people and wounding 50 others. The attack began around the time that government officials were expected to arrive at the campus for the opening of an Iranian book fair.', 2020, 11, 2, NULL, NULL, NULL, 'day', '2 November 2020', 64, 'https://en.wikipedia.org/wiki/2020_Kabul_University_attack'),
  ('Q106768320', 'May 2021 Kabul bombing', 'On 8 May 2021, a car bombing followed by two more improvised explosive device (IED) blasts occurred in front of Sayed al-Shuhada High School in Dashte Barchi, a predominantly Shia Hazara area in western Kabul, Afghanistan, leaving at least 90 people dead and 240 injured. The majority of the casualties were girls between 11 and 15 years old.', 2021, 5, 8, NULL, NULL, NULL, 'day', '8 May 2021', 56, 'https://en.wikipedia.org/wiki/2021_Kabul_school_bombing'),
  ('Q108102583', 'Fall of Kabul', 'On 15 August 2021, Afghanistan''s capital city of Kabul was captured by the Taliban after a major insurgent offensive that began in May 2021. It was the final action of the War in Afghanistan, and marked a total victory for the Taliban.', 2021, 8, 15, NULL, NULL, NULL, 'day', '15 August 2021', 75, 'https://en.wikipedia.org/wiki/Fall_of_Kabul_(2021)'),
  ('Q108170899', '2021 Afghan protests', 'Protests in Afghanistan held by Islamic democrats and feminists against the treatment of women by the Taliban began on 17 August 2021, following the fall of Kabul. Supported by the National Resistance Front (NRF), the protesters also demanded decentralization, multiculturalism, social justice, labor, education, and food.', 2021, 8, NULL, NULL, NULL, NULL, 'month', 'August 2021', 45, 'https://en.wikipedia.org/wiki/2021%E2%80%932022_Afghan_protests'),
  ('Q110604288', 'January 2022 Afghanistan earthquake', 'An earthquake measuring Mw 4.9, followed by a 5.3 Mw mainshock struck Badghis Province, Afghanistan, on January 17, 2022. The earthquake led to a large number of casualties for the tremor''s magnitude, with 30 dead and 49 injured.', 2022, 1, 17, NULL, NULL, NULL, 'day', '17 January 2022', 48, 'https://en.wikipedia.org/wiki/January_2022_Afghanistan_earthquakes'),
  ('Q112666390', 'June 2022 Afghanistan earthquake', 'A 4.0-kilometre (2.5 mi) deep earthquake measuring a magnitude (Mw) of 6.2 struck southeastern Afghanistan on 22 June 2022 at 01:24:36 AFT (on 21 June 2022 at 20:54:36 UTC). The earthquake had a maximum Modified Mercalli intensity of IX (Violent).', 2022, 6, 22, NULL, NULL, NULL, 'day', '22 June 2022', 66, 'https://en.wikipedia.org/wiki/June_2022_Afghanistan_earthquake'),
  ('Q117244307', '2023 Badakhshan earthquake', 'On 21 March 2023, a magnitude 6.5 earthquake struck Badakhshan Province, Afghanistan, with an intermediate depth of approximately 187 km (116 mi). The epicenter of the earthquake was 40 km (25 mi) south-southeast of Jurm.', 2023, 3, 21, NULL, NULL, NULL, 'day', '21 March 2023', 56, 'https://en.wikipedia.org/wiki/2023_Badakhshan_earthquake'),
  ('Q136033573', 'August 2025 Afghanistan earthquake', 'On 31 August 2025, at 23:47 AFT (19:17 UTC), an earthquake with a magnitude of 6.0 on the moment magnitude scale (Mw) struck eastern Afghanistan, near the border with Pakistan. The epicenter of the quake was located in Nurgal District, Kunar Province.', 2025, 8, 31, NULL, NULL, NULL, 'day', '31 August 2025', 67, 'https://en.wikipedia.org/wiki/2025_Kunar_earthquake'),
  ('Q136695875', 'November 2025 Afghanistan earthquake', 'On 3 November 2025, at 00:59 AFT (20:29 UTC, 2 November), an earthquake with a magnitude of 6.2 on the moment magnitude scale (Mw) struck northern Afghanistan. Around 31 people were killed, 1,172 were injured and many homes collapsed in Balkh and Samangan Provinces.', 2025, 11, 3, NULL, NULL, NULL, 'day', '3 November 2025', 48, 'https://en.wikipedia.org/wiki/2025_Balkh_earthquake'),
  ('Q138414208', '2026 Afghanistan–Pakistan War', 'Since February 2026, Pakistan and Afghanistan have been engaged in the most sustained cross-border conflict between the two countries since the Taliban''s 2021 return to power in Afghanistan. The conflict began with Pakistani airstrikes on alleged Pakistani Taliban (TTP) and Islamic State – Khorasan Province camps in eastern Afghanistan, and escalated within a week into what Pakistan''s defence minister, Khawaja Asif, called an "open war" fought under the codename Operation Ghazab lil-Haq.', 2026, 2, 21, NULL, NULL, NULL, 'day', '21 February 2026', 71, 'https://en.wikipedia.org/wiki/2026_Afghanistan%E2%80%93Pakistan_war');
